package com.wordlock.test;
import android.app.*;import android.appwidget.*;import android.os.*;import android.content.*;import android.widget.*;import android.speech.tts.TextToSpeech;import java.util.*;
public class MainActivity extends Activity {
LinearLayout l; SharedPreferences p; TextView word; TextToSpeech tts; boolean ready;
void button(String s,Runnable r){Button b=new Button(this);b.setText(s);b.setOnClickListener(v->r.run());l.addView(b);}
void select(String label,String key,String[] values,int def){TextView t=new TextView(this);t.setText(label);l.addView(t);Spinner s=new Spinner(this);s.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,values));s.setSelection(p.getInt(key,def));s.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> a){}public void onItemSelected(AdapterView<?> a,android.view.View v,int i,long id){int old=p.getInt(key,def);if(old!=i){p.edit().putInt(key,i).apply();WordWidget.refresh(MainActivity.this,key.equals("level"));showWord();}}});l.addView(s);}
void size(String label,String key,int def,int min,int max){TextView t=new TextView(this);l.addView(t);SeekBar b=new SeekBar(this);b.setMax(max-min);b.setProgress(p.getInt(key,def)-min);t.setText(label+": "+p.getInt(key,def));b.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){}public void onProgressChanged(SeekBar b,int n,boolean user){if(user){p.edit().putInt(key,n+min).apply();t.setText(label+": "+(n+min));WordWidget.refresh(MainActivity.this,false);}}});l.addView(b);}
void showWord(){if(word!=null){String[] w=WordWidget.WORDS[WordWidget.current(this)];word.setText(w[1]+" — "+w[2]+"\nÖğrenilen: "+p.getStringSet("learned",Collections.emptySet()).size()+" / "+WordWidget.WORDS.length);}}
public void onCreate(Bundle b){super.onCreate(b);p=WordWidget.prefs(this);tts=new TextToSpeech(this,status->{if(status==TextToSpeech.SUCCESS){ready=tts.setLanguage(Locale.US)>=0;}});ScrollView sc=new ScrollView(this);l=new LinearLayout(this);l.setOrientation(1);l.setPadding(36,36,36,36);sc.addView(l);TextView title=new TextView(this);title.setText("WordLock • Altın Fırça");title.setTextSize(26);l.addView(title);word=new TextView(this);word.setTextSize(20);l.addView(word);showWord();button("Yeni kelime",()->{WordWidget.refresh(this,true);showWord();});button("İngilizce telaffuz",()->{if(ready)tts.speak(WordWidget.WORDS[WordWidget.current(this)][1],TextToSpeech.QUEUE_FLUSH,null,"word");else Toast.makeText(this,"İngilizce ses motoru hazır değil",0).show();});button("Öğrendim",()->{Set<String> s=new HashSet<>(p.getStringSet("learned",Collections.emptySet()));s.add(WordWidget.WORDS[WordWidget.current(this)][1]);p.edit().putStringSet("learned",s).apply();WordWidget.refresh(this,true);showWord();});button("Öğrenilen kelimeler",()->{ArrayList<String> s=new ArrayList<>();for(String[] w:WordWidget.WORDS)if(p.getStringSet("learned",Collections.emptySet()).contains(w[1]))s.add(w[1]+" — "+w[2]);new AlertDialog.Builder(this).setTitle("Öğrenilen kelimeler").setItems(s.isEmpty()?new String[]{"Henüz kelime yok"}:s.toArray(new String[0]),null).setPositiveButton("Kapat",null).show();});select("Seviye","level",new String[]{"Tümü","A1","A2","B1","B2","C1","C2"},0);select("Otomatik değişim aralığı","interval",new String[]{"Her ekran açılışında","En az 5 dakika","En az 30 dakika","En az 1 saat","En az 1 gün"},0);Switch sw=new Switch(this);sw.setText("Öğrenilen kelimeleri atla");sw.setChecked(p.getBoolean("skip",true));sw.setOnCheckedChangeListener((v,on)->p.edit().putBoolean("skip",on).apply());l.addView(sw);select("Renk","color",new String[]{"Altın Fırça","Beyaz","Krem"},0);select("Yazı tipi","font",new String[]{"El yazısı","Klasik"},0);size("İngilizce boyutu","size",30,18,36);size("Türkçe boyutu","trsize",12,10,18);button("Widget ekle",()->{AppWidgetManager m=AppWidgetManager.getInstance(this);if(m.isRequestPinAppWidgetSupported())m.requestPinAppWidget(new ComponentName(this,WordWidget.class),null,null);else Toast.makeText(this,"Ana ekrandaki Widget menüsünü kullan",1).show();});button("Otomatik değişimi başlat",()->startForegroundService(new Intent(this,WordService.class)));button("Otomatik değişimi durdur",()->stopService(new Intent(this,WordService.class)));setContentView(sc);}
protected void onResume(){super.onResume();showWord();}protected void onDestroy(){if(tts!=null)tts.shutdown();super.onDestroy();}
}